const NOW = Date.UTC(2026, 9, 20, 18, 0, 0)
const HOUR = 3600000

const INITIAL: readonly ActivityItem[] = [
  { id: "sync", title: "文件已对齐", at: NOW - 2 * HOUR },
  { id: "note", title: "留下一条批注", at: NOW - 5 * HOUR },
