// Ported from kokonutUI (MIT) — https://github.com/kokonut-labs/kokonutui/blob/main/components/kokonutui/activity-terrain.tsx

/**
 * @author: @dorianbaffier
 * @description: Activity Terrain
 * @version: 1.0.0
 * @date: 2026-10-14
 * @license: MIT
 * @website: https://kokonutui.com
